fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    let n = s.len();
    let mut result: Vec<Vec<char>> = Vec::with_capacity(n);
    let mut prefix: Vec<char> = Vec::with_capacity(n);

    for c in s {
        // Extend the current prefix by one character
        prefix.push(c);
        // Push a clone of the prefix so far into the result
        result.push(prefix.clone());
    }

    result
}

